ext('c12_math_ch10',[
C("➕","सदिशों का जोड़",["त्रिभुज नियम","समांतर चतुर्भुज नियम","जोड़ क्रमविनिमेय","शून्य सदिश तत्समक"],"दो सदिशों को जोड़ने के लिए त्रिभुज नियम काम आता है। पहले सदिश के सिरे से दूसरे सदिश की शुरुआत करते हैं, तो परिणामी सदिश पहले की शुरुआत से दूसरे के सिरे तक होता है। समांतर चतुर्भुज नियम से भी यही परिणाम मिलता है। सदिशों का जोड़ क्रमविनिमेय होता है, और शून्य सदिश जोड़ में तत्समक है।"),
C("📏","इकाई सदिश",["परिमाण एक","दिशा वही","सदिश भाग उसका परिमाण","i, j, k अक्षों की दिशा में"],"वह सदिश जिसका परिमाण एक हो, इकाई सदिश कहलाता है। किसी भी सदिश की दिशा में इकाई सदिश निकालने के लिए उसे उसके परिमाण से भाग देते हैं। i, j और k क्रमशः x, y और z अक्षों की दिशा में इकाई सदिश हैं। इनसे हर सदिश को घटकों के रूप में लिखा जा सकता है।"),
C("🧮","अदिश गुणनफल के उपयोग",["दो सदिशों के बीच का कोण","लंबवत की जाँच","एक सदिश का दूसरे पर प्रक्षेप","कार्य की गणना"],"अदिश गुणनफल से दो सदिशों के बीच का कोण निकाला जा सकता है। अगर यह गुणनफल शून्य हो, तो दोनों सदिश एक-दूसरे के लंबवत होते हैं। इसका उपयोग एक सदिश को दूसरे पर प्रक्षेपित करने में भी होता है। भौतिकी में किसी बल द्वारा किया गया कार्य बल और विस्थापन के अदिश गुणनफल से निकलता है।"),
C("✖️","सदिश गुणनफल का अर्थ",["परिणाम एक सदिश","दोनों सदिशों के लंबवत","परिमाण: ab sin θ","समांतर चतुर्भुज का क्षेत्रफल"],"सदिश गुणनफल का परिणाम स्वयं एक सदिश होता है, जो दोनों दिए सदिशों के लंबवत होता है। उसका परिमाण दोनों सदिशों के परिमाण और उनके बीच के कोण की ज्या के गुणनफल के बराबर होता है। यह परिमाण उन सदिशों से बने समांतर चतुर्भुज के क्षेत्रफल के बराबर भी होता है। इसमें क्रम बदलने पर चिह्न बदल जाता है।"),
C("🔺","सदिशों से त्रिभुज का क्षेत्रफल",["दो भुजाओं के सदिश","उनका सदिश गुणनफल","परिमाण का आधा","निर्देशांकों से सीधा"],"अगर किसी त्रिभुज की दो भुजाओं को सदिशों के रूप में लिखा जाए, तो उनके सदिश गुणनफल के परिमाण का आधा त्रिभुज का क्षेत्रफल होता है। यह विधि विशेष रूप से तब काम आती है जब शीर्षों के निर्देशांक दिए हों। इसमें पहले भुजाओं के सदिश निकालते हैं और फिर उनका सदिश गुणनफल।"),
],5)
ext('c12_math_ch11',[
C("📐","रेखा के समीकरण के दो रूप",["सदिश रूप","कार्तीय रूप","बिंदु और दिशा-अनुपात","दो बिंदुओं से गुज़रती रेखा"],"त्रिविमीय ज्यामिति में रेखा का समीकरण दो रूपों में लिखा जाता है। सदिश रूप में एक बिंदु का स्थिति सदिश और दिशा के समांतर सदिश का एक अचर गुणज होता है। कार्तीय रूप में निर्देशांक और दिक्-अनुपात का प्रयोग होता है। दो बिंदुओं से गुज़रने वाली रेखा के लिए उन बिंदुओं के बीच के सदिश को दिशा माना जाता है।"),
C("↔️","तिर्यक रेखाएँ",["न समांतर, न प्रतिच्छेदी","अलग-अलग तलों में","न्यूनतम दूरी निकाली जाती","सदिश सूत्र से"],"त्रिविमीय आकाश में दो रेखाएँ ऐसी भी हो सकती हैं जो न समांतर हों और न एक-दूसरे को काटें। ऐसी रेखाओं को तिर्यक रेखाएँ कहते हैं। दोनों के बीच की न्यूनतम दूरी उनके दिशा सदिशों के सदिश गुणनफल और बिंदुओं को जोड़ने वाले सदिश की मदद से निकाली जाती है।"),
C("🧊","समतल के समीकरण",["अभिलंब रूप","बिंदु और अभिलंब सदिश","तीन बिंदुओं से गुज़रता","अक्ष-खंड रूप"],"समतल का समीकरण कई प्रकार से लिखा जा सकता है। अगर समतल के एक बिंदु और उसके अभिलंब की दिशा पता हो, तो समीकरण सीधे बन जाता है। तीन बिंदुओं के लिए पहले दो सदिश बनाकर उनका सदिश गुणनफल निकालते हैं, जो अभिलंब होता है। अक्षों को काटने वाले खंडों से भी समतल का समीकरण लिखा जा सकता है।"),
C("📏","बिंदु से समतल की दूरी",["बिंदु के निर्देशांक रखें","समतल का समीकरण","अभिलंब के परिमाण से भाग","दूरी सदा धनात्मक"],"किसी बिंदु से समतल की लंबवत दूरी निकालने के लिए बिंदु के निर्देशांक समतल के समीकरण में रखे जाते हैं। इस मान का निरपेक्ष मान लेकर अभिलंब के परिमाण से भाग देते हैं। दूरी हमेशा धनात्मक होती है, इसलिए निरपेक्ष मान ज़रूरी है। अगर मान शून्य आए तो बिंदु उसी समतल पर होता है।"),
C("📐","दो समतलों के बीच का कोण",["अभिलंबों के बीच का कोण","अदिश गुणनफल का उपयोग","समांतर: अभिलंब समांतर","लंबवत: अभिलंबों का गुणनफल शून्य"],"दो समतलों के बीच का कोण उनके अभिलंब सदिशों के बीच के कोण के बराबर होता है। इसे निकालने के लिए अभिलंबों का अदिश गुणनफल लेते हैं। अगर दोनों अभिलंब समांतर हों, तो समतल भी समांतर होंगे। अगर अभिलंबों का अदिश गुणनफल शून्य हो, तो दोनों समतल आपस में लंबवत होंगे।"),
],5)
ext('c12_math_ch12',[
C("🧵","एक पूरा उदाहरण: दर्जी की समस्या",["कमीज़ और पैंट बनाना","कपड़े और समय की सीमा","लाभ अधिकतम करना","चर x और y"],"मान लीजिए एक दर्जी कमीज़ और पैंट बनाता है। कपड़ा और काम का समय सीमित है, और प्रति कमीज़ और पैंट का लाभ अलग-अलग है। कमीज़ों की संख्या को x और पैंटों की संख्या को y मानकर उद्देश्य फलन लिखा जाता है। कपड़े और समय की सीमाओं से अवरोध असमिकाएँ बनती हैं, जिन्हें हल करके अधिकतम लाभ ढूँढ़ा जाता है।"),
C("📈","आलेख से सुसंगत क्षेत्र",["असमिका की रेखा खींचें","सही पक्ष चुनें","सभी असमिकाओं का उभयनिष्ठ भाग","यही सुसंगत क्षेत्र"],"सुसंगत क्षेत्र निकालने के लिए हर असमिका की सीमा-रेखा आलेख पर खींची जाती है। फिर परीक्षण बिंदु, जैसे मूल बिंदु, रखकर देखते हैं कि असमिका किस ओर लागू होती है। सभी असमिकाओं के उभयनिष्ठ भाग को छायांकित करते हैं। यही सुसंगत क्षेत्र है, जिसमें सारे संभव हल होते हैं।"),
C("🔺","कोने के बिंदुओं का परीक्षण",["सभी कोने के बिंदु निकालें","उद्देश्य फलन में रखें","सबसे बड़ा मान उच्चतम","सबसे छोटा मान निम्नतम"],"रैखिक प्रोग्रामन में उद्देश्य फलन का उच्चतम या निम्नतम मान हमेशा सुसंगत क्षेत्र के किसी कोने के बिंदु पर मिलता है। इसलिए सभी कोने के बिंदुओं के निर्देशांक निकालकर उद्देश्य फलन में रखते हैं। जो मान सबसे बड़ा हो वह उच्चतम है और जो सबसे छोटा हो वह निम्नतम। यही इस अध्याय का मुख्य विचार है।"),
C("♾️","असीमित क्षेत्र की स्थिति",["क्षेत्र अनंत तक फैला हो","कोने के बिंदुओं से निकले मान","नया खुला अर्धतल बनाएँ","तभी उच्चतम या निम्नतम"],"कभी सुसंगत क्षेत्र असीमित होता है। ऐसी स्थिति में कोने के बिंदुओं से मिले मान को और जाँचना पड़ता है। निम्नतम का मान तब मान्य होता है जब उद्देश्य फलन के उस मान से कम पर एक नया खुला अर्धतल बनाने पर वह असुसंगत क्षेत्र को नहीं काटता। यही शर्त उच्चतम के लिए भी विपरीत रूप में लगती है।"),
C("🍲","आहार समस्या",["पोषक तत्वों की न्यूनतम माँग","सस्ते खाद्य पदार्थ चुनना","न्यूनतम लागत","निम्नतमीकरण की समस्या"],"आहार समस्या में कुछ पोषक तत्वों की न्यूनतम मात्रा पूरी करनी होती है, और सबसे कम लागत में। अलग-अलग खाद्य पदार्थों की मात्राएँ चर मानकर पोषक तत्वों की शर्तों को असमिकाओं के रूप में लिखा जाता है। उद्देश्य फलन कुल लागत होता है, जिसका निम्नतम मान ज्ञात करना होता है।"),
],5)
ext('c12_math_ch13',[
C("🎲","एक उदाहरण: दो पासे",["कुल छत्तीस परिणाम","योग सात के छह परिणाम","प्रायिकता छह बटा छत्तीस","सरलीकृत एक बटा छह"],"दो पासे एक साथ फेंकने पर कुल छत्तीस संभव परिणाम होते हैं। इनमें से योग सात आने के परिणाम छह हैं, जैसे एक और छह, दो और पाँच, और इसी तरह आगे। इसलिए योग सात आने की प्रायिकता छह बटा छत्तीस होती है, जो सरल करने पर एक बटा छह है।"),
C("🧩","सप्रतिबंध प्रायिकता का अर्थ",["घटना B हो चुकी","तब घटना A की प्रायिकता","P(A∩B) बटा P(B)","संभावित क्षेत्र सीमित हो गया"],"सप्रतिबंध प्रायिकता का अर्थ है, यह मान लेना कि कोई घटना हो चुकी है और फिर दूसरी घटना की प्रायिकता निकालना। इसका सूत्र घटना A और B के एक साथ होने की प्रायिकता को घटना B की प्रायिकता से भाग देना है। इसमें नमूना समष्टि का क्षेत्र सीमित होकर केवल घटना B तक रह जाता है।"),
C("🔗","स्वतंत्र घटनाएँ",["एक घटना दूसरी को प्रभावित न करे","P(A∩B) = P(A) P(B)","सिक्का और पासा","अलग-अलग फेंके सिक्के"],"जब एक घटना के होने से दूसरी घटना की प्रायिकता पर कोई असर न पड़े, तो दोनों घटनाएँ स्वतंत्र कहलाती हैं। ऐसी घटनाओं के लिए साथ-साथ होने की प्रायिकता उनकी अलग-अलग प्रायिकताओं के गुणनफल के बराबर होती है। सिक्का उछालना और पासा फेंकना इसका सरल उदाहरण है।"),
C("🧪","बेज़ प्रमेय का उदाहरण",["दो मशीनों से बने सामान","एक सामान खराब निकला","किस मशीन का है","पूर्व और पश्चात प्रायिकता"],"मान लीजिए दो मशीनें एक कारखाने में सामान बनाती हैं और उनमें से कुछ खराब निकलते हैं। अगर एक खराब सामान मिला है, तो बेज़ प्रमेय से यह पता लगाया जा सकता है कि उसके किसी खास मशीन से बने होने की प्रायिकता कितनी है। यह नई जानकारी मिलने पर पुरानी प्रायिकता को सुधारने की विधि है।"),
C("📊","माध्य और प्रसरण",["यादृच्छिक चर का माध्य","प्रत्येक मान × प्रायिकता का योग","प्रसरण: फैलाव का माप","मानक विचलन वर्गमूल"],"यादृच्छिक चर का माध्य निकालने के लिए हर संभव मान को उसकी प्रायिकता से गुणा करके सबको जोड़ा जाता है। प्रसरण यह बताता है कि मान माध्य से कितने बिखरे हुए हैं। प्रसरण का वर्गमूल मानक विचलन कहलाता है। ये दोनों माप बंटन की आकृति समझने में बहुत उपयोगी हैं।"),
C("🪙","द्विपद बंटन के उदाहरण",["सिक्का दस बार उछालना","प्रत्येक बार सफलता या असफलता","n स्वतंत्र प्रयास","सफलता की प्रायिकता p"],"द्विपद बंटन तब काम आता है जब कोई प्रयोग बार-बार किया जाए, हर प्रयास स्वतंत्र हो और हर बार केवल दो ही परिणाम हों, सफलता या असफलता। जैसे सिक्का दस बार उछालने पर चित आने की संख्या। इसमें माध्य n गुणा p होता है, और प्रसरण n गुणा p गुणा q, जहाँ q बराबर एक में से p घटाया।"),
],5)
